import java.util.*;

class AncestorFinder {
    private int[][] up;
    private int LOG;

    public AncestorFinder(int n, int[] parent) {
        LOG = 1;
        while ((1 << LOG) <= n) LOG++;
        up = new int[LOG][n];
        up[0] = parent.clone();
        for (int j = 1; j < LOG; j++)
            for (int v = 0; v < n; v++) {
                int mid = up[j - 1][v];
                up[j][v] = mid == -1 ? -1 : up[j - 1][mid];  // 2^j = 2^(j-1) + 2^(j-1)
            }
    }

    public int kthAncestor(int node, int k) {
        for (int j = 0; k > 0 && node != -1; j++, k >>= 1) {
            if (j >= LOG) return -1;               // k is larger than any possible depth
            if ((k & 1) == 1) node = up[j][node];  // jump along each set bit of k
        }
        return node;
    }
}

