class AncestorFinder:
    def __init__(self, n: int, parent: List[int]):
        self.up = [parent[:]]
        for _ in range(n.bit_length()):
            p = self.up[-1]
            self.up.append([-1 if p[v] == -1 else p[p[v]] for v in range(n)])
    def kthAncestor(self, node: int, k: int) -> int:
        j = 0
        while k and node != -1:
            if k & 1:
                if j >= len(self.up): return -1
                node = self.up[j][node]
            k >>= 1; j += 1
        return node

